We encode these decisions via the following variables:
\begin{align*}
    y_{it}&=\begin{cases}
        1&\text{if the decision-maker attempts to open facility $i\in\mathcal{F}$ at time $t\in\mathcal{T}$}\\
        0&\text{otherwise.}
    \end{cases}
\end{align*}

We define the following variables:
\begin{equation} z_{it} = \begin{cases}
        1 & \text{if facility $i\in\mathcal{F}$ is open at time $t\in\mathcal{T}$, i.e. if}\ S_{it} = 1 \;\; \text{and}\;\; y_{it}=1\\ 
        0 & \text{otherwise, i.e., if}\ \text{if}\ S_{it} = 0 \;\; \text{or}\;\; y_{it}=0
    \end{cases}
\end{equation}

\begin{enumerate}
    \item $\Theta$ is a compact set and $\mathcal{X}$ is a compact set.
    \item $f_\theta(\boldsymbol{x})$ is a twice continuously-differentiable function of $\theta$ uniformly in $\boldsymbol{x} \in \mathcal{X}$, and $f_\theta(\boldsymbol{x})$ is a continuous function in $\boldsymbol{x}$ for every $\theta$. 
    \item The conditional Fisher information matrix is positive definite for all $\boldsymbol{x}\in\mathcal{X}$:
    \[\mathcal{I}(\boldsymbol{x},\theta) = \frac{1}{f_\theta(\boldsymbol{x})(1-f_\theta(\boldsymbol{x}))}\frac{\partial f_\theta(\boldsymbol{x})}{\partial \theta}\frac{\partial f_\theta(\boldsymbol{x})}{\partial \theta^T} \]
\end{enumerate}

