We introduce the following parameters $\alpha_T$, $\zeta_T$, $c_0$ for any $r\neq1$. Note that, if $r<1$, then $1-r<\alpha_T<1$ as $T\geq2$ and that $\alpha_T$ converges exponentially fast to $1$.
\begin{align*}
	\alpha_T=\frac{1}{1-r^T}\qquad\qquad
	\zeta_T=\frac{\frac{1}{r^T}-1}{1-r}\cdot\left(\frac{1}{r}\right)^{\frac{r}{1-r}-T\alpha_T}\cdot c_0^{\alpha_T\cdot(1-r)} \qquad\qquad c_0 = \frac{1}{1-(1-p)\varepsilon}
\end{align*}

This procedure involves tentatively opening $A^\dagger_t$ facilities in each period $t\in\mathcal{T}$, given as follows::
\begin{equation} A^\dagger_t=
            r^{-\frac{1}{1-r}\left(t-T\cdot\alpha_T\cdot(1-r^t)\right)}\cdot c_0^{\alpha_T\cdot(1-r^t)}\cdot \ell^{\alpha_T(1-r^t)},
\end{equation}
where $\ell$ is the unique positive solution to the following equation:
\begin{equation} \sum_{t=1}^T A^\dagger_t= c_0 \left(m + \varepsilon\cdot p\cdot\zeta_T\cdot m^{\alpha_T\cdot(1-r)}+ \Delta(m)\right);\   \ \Delta(m) = \begin{cases}
    \sqrt{\frac{c_0}{2}\log \frac{2}{\delta}}\sqrt{m} & \text{if }p \neq 1,\\
    -\Phi^{-1}(\delta) \sqrt{2\varepsilon \zeta_T} m^{\frac{1}{2}\cdot \alpha_T \cdot (1-r)}& \text{if }p = 1.
\end{cases}
\end{equation}

Repeat, for $t=1,\cdots,T$:
\begin{itemize}
    \item[] \textbf{1. Optimize.} Tentatively open $A^\dagger_t$ facilities, according to Equations~\eqref{eq:solution}--\eqref{eq:solution_eq}.
    \item[] \textbf{2. Commit.} Observe $B^\dagger_t\sim \mathrm{Bino}\left(A_t, 1- \frac{\varepsilon\cdot p}{\left(\sum_{s=1}^{t-1} A_s +1\right)^r}-\varepsilon\cdot(1-p)\right)$, and update $N^\dagger_t=N^\dagger_{t-1} + B^\dagger_t$.
\end{itemize}

We define a deterministic approximation of the problem where $\delta=0$ and $B_t$ always realizes at the mean value. The problem, referred to as  Problem~\eqref{prob:main_det}, is given by:
\begin{align} \tag{$\mathcal{P}^D$}
    \min\ \left\{\ \sum_{t=1}^T A_t \ \ \bigg|\ \ \sum_{t=1}^TA_t \left(1- \frac{\varepsilon\cdot p}{\left(\sum_{s=1}^{t-1} A_s +1\right)^r}-\varepsilon\cdot(1-p)\right)\geq m\right\}.
\end{align}

Lemma~\ref{lem:main_det} elicits the asymptotic solution of Problem~\eqref{prob:main_det}. The proof elicits the Karush–Kuhn–Tucker (KKT) conditions and performing leading-order and leading-coefficient analyses to identify the asymptotic dependency on $m$ of the deterministic solution.

\begin{lemma}[Asymptotic solution of Problem~\eqref{prob:main_det}] Let $m^D(\varepsilon, T)$ be the optimal objective value of Problem~\eqref{prob:main_det}, and $A^D,\cdots, A^D$ be its solution. For any $T\geq 2$, we have as $m \to \infty$: 
\begin{align}
       & A^D_t = r^{-\frac{1}{1-r}\left(t-T\cdot\alpha_T\cdot(1-r^t)\right)}\cdot c_0^{\alpha_T\cdot(1-r^t)}\cdot m^{\alpha_T\cdot(1-r^t)}+ o\left(m^{\alpha_T\cdot(1-r^t)}\right),\ \forall t=1,\cdots,T, \\
       &m^D(\varepsilon, T) = c_0\left( m+\varepsilon\cdot p\cdot \zeta_T \cdot m^{\alpha_T\cdot(1-r)} +  o\left(m^{\alpha_T\cdot(1-r)}\right)\right). \end{align}
\end{lemma}

The solution of the deterministic problem provides insights into the structure of Algorithm~\ref{ALG}, which constructs a solution that matches Equation~\eqref{eq:deterministic_decision} with a buffer to handle uncertainty. This observation follows from the fact that $\ell$ is on the order of $\Theta(m)$, which we prove in Remark~\ref{rem:lm}.
\begin{remark} For $m$ large enough, we have: $m- m^{\alpha_T \cdot (1-r)} \leq \ell\leq m + \Delta(m)$.
\end{remark}

We can then show that the solution from Algorithm~\ref{ALG} satisfies the chance constraint as $m\to\infty$, thus providing an asympotically feasible solution of the stochastic problem~\eqref{prob:main}. Algorithm~\ref{ALG} therefore yields an upper bound to Problem~\eqref{prob:main}. The proof leverages concentration inequalities across time periods $1,\cdots,T$, by expressing each value of $\mathbb{E}(B_t)$ from Equations~\eqref{eq:solution}--\eqref{eq:solution_eq}. We leverage Hoeffding's inequality when $p\neq 1$; however, it may no longer lead to asymptotically tight bounds when $p=1$, so we leverage the Berry-Esseen theorem instead. This bounds the probability that at least $m$ facilities get successfully opened by the end of the planning horizon.

\begin{lemma}[Upper bound] The solution of Algorithm~\ref{ALG} satisfies $\lim_{m \to \infty} \mathbb{P}(N^\dagger_T \geq m) \geq 1-\delta$.
\end{lemma}

Finally, Lemma~\ref{lem:main_lower} establishes the lower bound of Theorem~\ref{thm:main}. When $p=1$, the proof shows that $B_t$ remains close to its expected value at each time $t=1,\cdots,T$, using Bernstein's concentration inequality across facilities; it then calls Lemma~\ref{lem:main_det} conditionally on $B_1\approx\mathbb{E}(B_1),\cdots,B_T\approx\mathbb{E}(B_T)$ to bound the total number of facilities $m^*(\varepsilon, T)$. In particular, Bernstein's concentration inequality exploits that the asymptotic error on facility openings is small, so the variance term provides an asymptotically better bound than with Hoeffding's inequality.  When $p\neq1$, it uses the Berry-Esseen theorem to show that the lower bound is necessary to satisfy the chance constraint.

\begin{lemma}[Lower bound] Assume that $\delta = o\left(m^{\alpha_T\cdot(1-r)-1}\right)$. Let $m^*(\varepsilon, T)$ denote the optimal solution of Problem~\eqref{prob:main}. The following holds, as $m \to \infty$:
  \[m^*(\varepsilon, T) \geq   \begin{cases}
  c_0\left(m +\max\{-\Phi^{-1}(\delta)\sqrt{2\varepsilon(1-p)m},\varepsilon\cdot p\cdot\zeta_T\cdot m^{\alpha_T\cdot(1-r)}\}\right) & \text{if }p \neq 1\\
      c_0\left(m + \varepsilon\cdot p\cdot\zeta_T\cdot m^{\alpha_T\cdot(1-r)} +  o\left(m^{\alpha_T\cdot(1-r)}\right)\right) & \text{if }p=1
  \end{cases}\]
\end{lemma}

Together, the lemmas show that the strategy detailed in Algorithm~\ref{ALG} is asymptotically optimal up to second-leading order terms, therefore completing the proof of the theorem.

We define a deterministic approximation of the problem where $\delta=0$ and $B_t$ always realizes at the mean value. The problem, referred to as  Problem~\eqref{prob:main_det}, is given by:
\begin{align} \tag{$\mathcal{P}^D$}
    \min\ \left\{\ \sum_{t=1}^T A_t \ \ \bigg|\ \ \sum_{t=1}^TA_t \left(1- \frac{\varepsilon\cdot p}{\left(\sum_{s=1}^{t-1} A_s +1\right)^r}-\varepsilon\cdot(1-p)\right)\geq m\right\}.
\end{align}

Lemma~\ref{lem:main_det} elicits the asymptotic solution of Problem~\eqref{prob:main_det}. The proof elicits the Karush–Kuhn–Tucker (KKT) conditions and performing leading-order and leading-coefficient analyses to identify the asymptotic dependency on $m$ of the deterministic solution.

\begin{lemma}[Asymptotic solution of Problem~\eqref{prob:main_det}] Let $m^D(\varepsilon, T)$ be the optimal objective value of Problem~\eqref{prob:main_det}, and $A^D,\cdots, A^D$ be its solution. For any $T\geq 2$, we have as $m \to \infty$: 
\begin{align}
       & A^D_t = r^{-\frac{1}{1-r}\left(t-T\cdot\alpha_T\cdot(1-r^t)\right)}\cdot c_0^{\alpha_T\cdot(1-r^t)}\cdot m^{\alpha_T\cdot(1-r^t)}+ o\left(m^{\alpha_T\cdot(1-r^t)}\right),\ \forall t=1,\cdots,T, \\
       &m^D(\varepsilon, T) = c_0\left( m+\varepsilon\cdot p\cdot \zeta_T \cdot m^{\alpha_T\cdot(1-r)} +  o\left(m^{\alpha_T\cdot(1-r)}\right)\right). \end{align}
\end{lemma}

The solution of the deterministic problem provides insights into the structure of Algorithm~\ref{ALG}, which constructs a solution that matches Equation~\eqref{eq:deterministic_decision} with a buffer to handle uncertainty. This observation follows from the fact that $\ell$ is on the order of $\Theta(m)$, which we prove in Remark~\ref{rem:lm}.
\begin{remark} For $m$ large enough, we have: $m- m^{\alpha_T \cdot (1-r)} \leq \ell\leq m + \Delta(m)$.
\end{remark}

We can then show that the solution from Algorithm~\ref{ALG} satisfies the chance constraint as $m\to\infty$, thus providing an asympotically feasible solution of the stochastic problem~\eqref{prob:main}. Algorithm~\ref{ALG} therefore yields an upper bound to Problem~\eqref{prob:main}. The proof leverages concentration inequalities across time periods $1,\cdots,T$, by expressing each value of $\mathbb{E}(B_t)$ from Equations~\eqref{eq:solution}--\eqref{eq:solution_eq}. We leverage Hoeffding's inequality when $p\neq 1$; however, it may no longer lead to asymptotically tight bounds when $p=1$, so we leverage the Berry-Esseen theorem instead. This bounds the probability that at least $m$ facilities get successfully opened by the end of the planning horizon.

\begin{lemma}[Upper bound] The solution of Algorithm~\ref{ALG} satisfies $\lim_{m \to \infty} \mathbb{P}(N^\dagger_T \geq m) \geq 1-\delta$.
\end{lemma}

Thus, the result yields asymptotically-tight regret rates up to the second-leading order:
	$$\texttt{Regret}=\begin{cases}
	    c_0\cdot\varepsilon\cdot p\cdot\zeta_T\cdot m^{\alpha_T\cdot(1-r)}+o\left(m^{\alpha_T\cdot(1-r)}\right)&\text{if $p=1$ or if ($p\neq1$ and $\alpha_T\cdot(1-r)\geq1/2$)}\\
        \Theta(\sqrt m)&\text{$p\neq1$ and $\alpha_T\cdot(1-r)<1/2$}
	\end{cases}$$

Moreover, we define the following variables to track the impact on customer coverage.
\begin{align*}
    s_{jt}&=\begin{cases}
        1&\text{if customer $j \in \mathcal{C}$ is served at time $t\in\mathcal{T}$, i.e., if there exists $i\in\mathcal{F}_j$ such that $z_{it}=1$}\\
        0&\text{otherwise.}
    \end{cases}
\end{align*}

Specifically, the algorithm solves a deterministic approximation of Problem~\eqref{prob:network}, with the following buffer to handle the chance constraints:
\begin{equation*}
	\Delta_G(m) = \begin{cases}
		-\Phi^{-1}\left(\frac{\delta}{2}\right)d_\star^2\sqrt{2\varepsilon c_0 m}& \text{if }p\neq1,\\
			-\Phi^{-1}\left(\frac{\delta}{2}\right)d_\star^2\sqrt{\varepsilon \zeta_T m^{\alpha_T \cdot (1-r)}}& \text{if }p =1.
	\end{cases}
\end{equation*}

\textbf{Optimize.} Solve the following optimization problem. Record solution $y^\dagger_{it}$ for $i\in\mathcal{F}$ and $t=1,\cdots, T$.
\begin{align}
    \min \quad & \sum_{t=1}^T \sum_{i=1}^n y_{it} \tag{$\mathcal{P}_N^\dagger$}\\
    \quad& \sum_{j=1}^q \left(1-\prod_{\tau=1}^T \left(\frac{\varepsilon\cdot p }{\left(\sum_{s=1}^{\tau-1} \sum_{i=1}^n y_{is} +1\right)^r}+\varepsilon\cdot(1-p)\right)^{\sum_{i \in \mathcal{F}_j} y_{i\tau}}\right) \geq m+\Delta_G(m),\nonumber\\
    \quad& y_{it}\in\{0,1\},\ \forall i\in \mathcal{F}, \ \forall t\in\mathcal{T}\nonumber
\end{align}

Repeat, for $t=1,\cdots,T$:
\begin{itemize}
    \item[] \textbf{Commit.} Observe $z_{it}\sim \mathrm{Ber}\left(1-\frac{\varepsilon\cdot p}{\left(\sum_{s=1}^{\tau-1} \sum_{i=1}^n y_{is} +1\right)^r}-\varepsilon\cdot(1-p)\right)$ for all $i\in\mathcal{F}$ such that $y^\dagger_{it}=1$.
    \item[] \textbf{Serve.} Update variables $s_{jt}=1$ for all $j\in\mathcal{C}_i$, $i\in\mathcal{F}$ such that $y^\dagger_{it}=1$.
\end{itemize}

In star graphs, Problem~\eqref{prob:network_ALG} therefore involves finding the largest possible threshold $n_0$ such that there exist subsequent thresholds $n_0\leq n_1 \leq \cdots \leq n_T=n$ satisfying
\begin{align*}
    \sum_{i=n_0+1}^n \deg(i)-\sum_{t=1}^T\sum_{i=n_{t-1}+1}^{n_t}\left(\frac{\varepsilon \deg(i)}{\left(n_{t}-n_0 +1\right)^r}+\varepsilon\cdot(1-p)\right)\geq m+\Delta_G(m)
\end{align*}

For any value of $n_0$, we therefore solve the following subproblem:
\begin{equation} \min\quad\left\{\sum_{t=1}^T\sum_{i=n_{t-1}+1}^{n_t}\left(\frac{\varepsilon\deg(i)}{\left(n_{t}-n_0 +1\right)^r}+\varepsilon\cdot(1-p)\right)\ \bigg|\ n_0\leq n_1 \leq \cdots \leq n_T=n\right\}\tag{$\mathcal{P}_0^\dagger$}.
\end{equation}

Iterate between Steps 1-3, until $\overline n_0-\underline n_0\leq 1$.
\begin{itemize}
    \item[] \textbf{Step 1.} Solve Problem~\eqref{eq:SP} as a shortest path problem; retrieve solution $n_1^*(n_0),\cdots, n_{T-1}^*(n_0)$.
    \item[] \textbf{Step 2.} If $\displaystyle\sum_{i=n_0+1}^n \deg(i)-\sum_{t=1}^T\sum_{i=n_{t-1}^*(n_0)+1}^{n_t}\left(\frac{\varepsilon \deg(i)}{\left(n_{t}^*(n_0)-n_0 +1\right)^r+\varepsilon\cdot(1-p)}\right)\geq m+\Delta_G(m)$, update $\overline{n}_0 = n_0$; otherwise, update $\underline{n}_0 = n_0+1$.
    \item[] \textbf{Step 3.} Update $n_0 = \left\lfloor\frac{\overline{n}_0 + \underline{n}_0}{2}\right\rfloor$.
\end{itemize}

We select the weight $w$ via one-dimensional line search between $1/d_\star$ and 1:
\begin{equation} \max\quad\left\{\texttt{STAR}(\mathcal{G}_w)\ \mid\ 1/d_\star \leq w \leq 1\right\}\tag{$\mathcal{P}_w^\dagger$}.
\end{equation}

Repeat Steps 1 -2, until breaking condition is met.
\begin{itemize}
    \item[] \textbf{Step 1.} Select $i_0\in\mathcal{F}$ and $t_0\in\mathcal{T}$ such that $y^*_{i_0,t_0}=1$. Define candidate solution
    $$\widetilde y_{it}^\dagger=\begin{cases}
        y_{it}^*&\text{for all $(i,t)\in\mathcal{F}\times\mathcal{T}\setminus\{(i_0,t_0)\}$}\\
        0&\text{if $i=i_0$ and $t=t_0$}
    \end{cases}$$
    \item[] \textbf{Step 2.} Update $y^*_{i_0,t_0}\gets0$ if the following condition is met. Otherwise, break.
    $$\sum_{j=1}^q \left(1-\prod_{\tau=1}^T \left(\frac{\varepsilon\cdot p}{\left(\sum_{s=1}^{\tau-1} \sum_{i=1}^n \widetilde y_{is}^\dagger +1\right)^r}+\varepsilon\cdot(1-p)\right)^{\sum_{i \in \mathcal{F}_j} \widetilde y_{i\tau}^\dagger}\right) \geq m+\Delta_G(m)$$
\end{itemize}
\item \textbf{Output:} $\boldsymbol{y}^*$

\textbf{Step 1.} Select $i_0\in\mathcal{F}$ and $t_0\in\mathcal{T}$ such that $y^*_{i_0,t_0}=1$. Define candidate solution
    $$\widetilde y_{it}^\dagger=\begin{cases}
        y_{it}^*&\text{for all $(i,t)\in\mathcal{F}\times\mathcal{T}\setminus\{(i_0,t_0)\}$}\\
        0&\text{if $i=i_0$ and $t=t_0$}
    \end{cases}$$

We first prove that $\widehat{\theta}_t$ is a consistent estimator.
    \begin{lemma} For every $\varepsilon_0, \varepsilon_1,\gamma>0$, there exists $a$ such that, for all $N_{t-1}\geq a$,
             \begin{align}
            \mathbb{P}\left(\|\widehat{\theta}_t-\theta\|_2\geq  \frac{\varepsilon_0}{(N_{t-1})^{1/2-\gamma}}\right)\leq\frac{\varepsilon_1}{(N_{t-1})^{1/2}} \end{align}
    \end{lemma} 
    \proof{Proof of Lemma~\ref{lem:mle}}
Per Equation~\eqref{eq:mle_estimation}, $\widehat{\theta}_t$ is the (conditional) maximum likelihood estimator based on independent, but not necessarily identically distributed, observations. While the facility success indicators $S_{it}$ may in general depend on prior facility openings, conditioning on the features $\bm{x}_i$ fixes the success probability $\eta_i = f_\theta(\bm{x}_i)$. As a result, the $S_{it}$ become conditionally independent across $i$. Since $y_{it}=1$ is chosen randomly with replacement among the set of facilities with $h_t(\boldsymbol{x}_i)=1$, this also implies that $y_{it}$ are conditionally independent across $i$ given $h_t(\boldsymbol{x}_i)=1$. In particular, this implies that $z_{it}$, determined by $S_{it}$ and $y_{it}$ to be conditionally independent fixing $\boldsymbol{x}_i$ and $h_t(\boldsymbol{x}_i)$. This allows standard properties of maximum likelihood estimation to apply. Due to the regularity conditions in Assumption~\ref{ass:regularity}, we obtain the consistency of the estimator from the general theory of MLE estimation \citep[e.g.,][]{hoadley1971asymptotic}:
        $\sqrt{N_{t-1}}\left(\widehat{\theta}_t -\theta\right)\xrightarrow{d} N(0,\boldsymbol{\Sigma})$ for some covariance matrix $\boldsymbol{\Sigma}$. Furthermore, $z_{is}$ is Bernoulli, hence sub-Gaussian. By concentration inequality of sub-Gaussian maximum likelihood estimators \citep[see e.g.][]{yang2024concentration}, we have:
        \[\mathbb{P}(\|\widehat{\theta}_t-\theta\|_2>\varepsilon)\leq 2\exp\left(-\frac{\varepsilon^2N_{t-1}}{C}\right)\]
        where $C$ is an absolute constant. Then, for any $\gamma>0$, we have that:
        \begin{equation*}
   \mathbb{P}\left(\|\widehat{\theta}_t-\theta\|_2\geq  \frac{\varepsilon}{(N_{t-1})^{1/2-\gamma}}\right)\leq2\exp\left(-\frac{\varepsilon^2 N_{t-1}^{2\gamma}}{C}\right) \leq \frac{\varepsilon_1}{(N_{t-1})^{1/2}}
        \end{equation*}
        where the last inequality is true for all $N_{t-1}\geq a$ for $a$ sufficiently large.
    \hfill\Halmos

    Next, we bound the accuracy of the resulting selections from the best possible classifier, as a function of the functions $f_{\widehat\theta_t}(\boldsymbol{x})$ and $f_{\theta}(\boldsymbol{x})$ and of the concentration of $f_{\theta}(\boldsymbol{x})$ around 0.5.
    \begin{lemma} The following holds:
    \[\left|\mathbb{P}\left(S_{it}=1 \mid h_t(\boldsymbol{x}_i)=1\right)- \mathbb{P}\left(S_{it}=1 \mid h^*(\boldsymbol{x}_i)=1\right)\right|\leq\mathbb{P}\left( \left|f_{\theta}(\boldsymbol{x}_i) - \frac{1}{2}\right| < \varepsilon \right)
    + \mathbb{P}\left( \left|f_{\widehat\theta_t}(\boldsymbol{x}_i) - f_{\theta}(\boldsymbol{x}_i)\right| > \varepsilon \right)\]
    \end{lemma}
    \proof{Proof of Lemma~\ref{lem:bound_classification}}
    The result is derived as follows, where $p_X(\cdot)$ denotes the probability distribution function of $\mathcal{Q}$ (Assumption~\ref{ass:sampling}):
\begin{align*}
& \left|\mathbb{P}\left(S_{it}=1 \mid h_t(\boldsymbol{x}_i)=1\right)- \mathbb{P}\left(S_{it}=1 \mid h^*(\boldsymbol{x}_i)=1\right)\right|\\
=& \left| \int_{f_{\widehat\theta_t}(\boldsymbol{x}_i) > \frac{1}{2}} f_{\theta}(\boldsymbol{x}_i) p_X(\boldsymbol{x}_i) \, \mathrm{d} x 
     - \int_{f_{\theta}(\boldsymbol{x}_i) > \frac{1}{2}} f_{\theta}(\boldsymbol{x}_i) p_X(\boldsymbol{x}_i) \, \mathrm{d} x \right| \\
=& \left| \int_{f_{\widehat\theta_t}(\boldsymbol{x}_i) > \frac{1}{2}, f_{\theta}(\boldsymbol{x}_i) < \frac{1}{2}} f_{\theta}(\boldsymbol{x}_i) p_X(\boldsymbol{x}_i) \, \mathrm{d} x + \int_{f_{\widehat\theta_t}(\boldsymbol{x}_i) < \frac{1}{2}, f_{\theta}(\boldsymbol{x}_i) > \frac{1}{2}} f_{\theta}(\boldsymbol{x}_i) p_X(\boldsymbol{x}_i) \, \mathrm{d} x \right| \\
\leq& \left| \int_{f_{\widehat\theta_t}(\boldsymbol{x}_i) > \frac{1}{2}, f_{\theta}(\boldsymbol{x}_i) < \frac{1}{2} - \varepsilon} f_{\theta}(\boldsymbol{x}_i) p_X(\boldsymbol{x}_i) \, \mathrm{d} x +\int_{f_{\widehat\theta_t}(\boldsymbol{x}_i) < \frac{1}{2}, f_{\theta}(\boldsymbol{x}_i) > \frac{1}{2} + \varepsilon} f_{\theta}(\boldsymbol{x}_i) p_X(\boldsymbol{x}_i) \, \mathrm{d} x + \int_{\left|f_{\theta}(\boldsymbol{x}_i) - \frac{1}{2}\right| < \varepsilon} f_{\theta}(\boldsymbol{x}_i) p_X(\boldsymbol{x}_i) \, \mathrm{d} x \right| \\
\leq& \left| \int_{\left|f_{\theta}(\boldsymbol{x}_i) - \frac{1}{2}\right| < \varepsilon} f_{\theta}(\boldsymbol{x}_i) p_X(\boldsymbol{x}_i) \, \mathrm{d} x \right| + \left| \int_{\left|f_{\widehat\theta_t}(\boldsymbol{x}_i) - f_{\theta}(\boldsymbol{x}_i)\right| > \varepsilon} f_{\theta}(\boldsymbol{x}_i) p_X(\boldsymbol{x}_i) \, \mathrm{d} x \right| \\
\leq& \mathbb{P}\left( \left|f_{\theta}(\boldsymbol{x}_i) - \frac{1}{2}\right| < \varepsilon \right)
    + \mathbb{P}\left( \left|f_{\widehat\theta_t}(\boldsymbol{x}_i) - f_{\theta}(\boldsymbol{x}_i)\right| > \varepsilon \right).
\end{align*}
This completes the proof of the lemma.
    \hfill\Halmos
    \subsubsection*{Proof of Proposition~\ref{prop:MLE}}
    Fix $\varepsilon,\gamma>0$. Since $N_t=\mathcal{O}(m)$ for all $t$, so we write $N_t\leq Km$ for some constant $K$ and for $m\geq m_A$. Per Assumption~\ref{ass:regime}, we can define $m_B$ such that $\frac{m}{M}\leq\frac{\varepsilon}{3K(N_{t-1})^{1/2-\gamma}}$ for all $m \geq m_B$. This implies that:
    \begin{equation}
        \mathbb{P}(y_{i\tau}=1\ \text{for $\tau\leq t-1$})\leq \frac{Km}{M} \leq \frac{\varepsilon}{3(N_{t-1})^{1/2-\gamma}} \end{equation}
    Now define $\varepsilon_0>0$ such that $\frac{C\varepsilon_0^\alpha}{3^\alpha}=\frac{\varepsilon}{3}$. We proceed to prove the main result:
\begin{align*}
1-\mu_t=&\mathbb{P}(S_{it}=1 \mid y_{i1}=\cdots=y_{i1,t-1}=0\ ;\ h_t(\boldsymbol{x}_i)=1)\\
=&\frac{\mathbb{P}(S_{it}=1 \mid h_t(\boldsymbol{x}_i)=1)-\mathbb{P}(y_{i\tau}=1\ \text{for $\tau\leq t-1$} \mid h_t(\boldsymbol{x}_i)=1)\mathbb{P}(S_{it}=1 \mid h_t(\boldsymbol{x}_i)=1, y_{i\tau}=1\ \text{for $\tau\leq t-1$})}{\mathbb{P}(y_{i1}=\cdots=y_{i1,t-1}=0 \mid h_t(\boldsymbol{x}_i)=1)}\\
\geq& \mathbb{P}(S_{it}=1 \mid h_t(\boldsymbol{x}_i)=1)-\mathbb{P}(y_{i\tau}=1\ \text{for $\tau\leq t-1$} \mid h_t(\boldsymbol{x}_i)=1)\\
\geq&\mathbb{P}(S_{it}=1 \mid h_t(\boldsymbol{x}_i)=1)-\frac{\varepsilon}{3(N_{t-1})^{1/2-\gamma}}\\
\geq&\mathbb{P}(S_{it}=1 \mid h^*(\boldsymbol{x}_i)=1)-\frac{\varepsilon}{3(N_{t-1})^{1/2-\gamma}}- \mathbb{P}\left( \left|f_{\theta}(\boldsymbol{x}_i) - \frac{1}{2}\right| < \frac{\varepsilon_0}{3(N_{t-1})^{1/2-\gamma}} \right)\\
    &-\mathbb{P}\left( \left|f_{\widehat\theta_t}(\boldsymbol{x}_i) - f_{\theta}(\boldsymbol{x}_i)\right| > \frac{\varepsilon_0}{3(N_{t-1})^{1/2-\gamma}} \right),
\end{align*}
