Again, the only non-trivial change from Theorem~\ref{thm:main} comes from calculating the optimal solution of the its deterministic approximation, formulated as follows. The solution is given in Lemma~\ref{lem:ws_det}.
{\small\begin{align}
    		    \min\ \left\{\ cA^D_0+ \sum_{t=1}^T A^{D}_t \ \ \bigg|\ \ \sum_{t=1}^TA^{D}_t \left(1- \frac{\varepsilon\cdot p}{\left(A^D_0+\sum_{s=1}^{t-1} A^D_s +1\right)^r}-\varepsilon\cdot(1-p)\ \right)=m\right\} \tag{$\mathcal{P}^{D}_{WS}$}
		\end{align}}

Let us define $\gamma_\star>0$ and $\beta_\star\in[0,1)$ such that $A_0^D=\gamma_\star\cdot m^{\beta_\star}+o\left(m^{\beta_\star}\right)$. Unlike in Lemma~\ref{lem:QtmN_det}, $\gamma_\star$ and $\beta_\star$ are decision variables, reflecting the amount of offline data to be acquired. As in Lemma~\ref{lem:QtmN_det}, we can define $u_t = A^D_0 + \sum_{s=1}^t A^{D}_s + 1$ for $t=1,\cdots,T$, and derive:
\begin{equation*}
    u_t=r^{-\frac{1}{1-r}\left(t-T\cdot\alpha_T\cdot(1-r^t)\right)}\cdot \left(\frac{c_0}{\gamma_\star}\right)^{\alpha_T\cdot(1-r^t)}\cdot m^{(1-\beta_\star)\alpha_T\left(1-r^t\right) + \beta_\star}+o\left(m^{(1-\beta_\star)\alpha_T\left(1-r^t\right) + \beta_\star}\right),
\end{equation*}
which achieves an objective of
$$c_0 \left(m + \varepsilon\cdot p\cdot\zeta_T\cdot \gamma_\star^{-\alpha_T(1-r)}\cdot m^{(1-\beta_\star)\cdot\alpha_T\cdot(1-r)+\beta_\star(1-r)}\right)+o\left(m^{(1-\beta_\star)\cdot\alpha_T\cdot(1-r)+\beta_\star(1-r)}\right).$$

As $m \to \infty$, the minimum is achieved when:
$$(1-\beta_\star)\cdot\alpha_T\cdot(1-r)+\beta_\star(1-r)=\beta_\star$$
Solving this equation gives $\beta_\star=\frac{\alpha_T(1-r)}{r+\alpha_T(1-r)}$. Recalling the definition of $\alpha_T=\frac{1}{1-r^T}$, we obtain: $\beta_\star=\frac{1-r}{1-r^{T+1}}=(1-r)\alpha_{T+1}$. We get $A^D_0 = \gamma_\star\cdot m^{(1-r)\cdot\alpha_{T+1}}$ and:
\begin{equation*}
    u_t=r^{-\frac{1}{1-r}\left(t-T\cdot\alpha_T\cdot(1-r^t)\right)}\cdot \left(\frac{c_0}{\gamma_\star}\right)^{\alpha_T\cdot(1-r^t)}\cdot m^{\alpha_{T+1}(1-r^{t+1})}+o\left(m^{\alpha_{T+1}(1-r^{t+1})}\right)
\end{equation*}

Proceeding as in the proof of Lemma~\ref{lem:QtmN_det}, we derive:
\begin{align*}
   \left(1-(1-p)\varepsilon)\right)\sum_{t=1}^T A^D_t
   &= m+\varepsilon\cdot p\cdot\zeta_T\cdot \gamma_\star^{-\alpha_T\cdot(1-r)}\cdot m^{(1-r)\cdot\alpha_{T+1}}+ o\left(m^{(1-r)\cdot\alpha_{T+1}}\right)
\end{align*}

The adaptive algorithm is specified in Algorithm~\ref{alg:adaptive}. At each time period $t=1,\cdots,T-1$, it solves Problem~$\left(\mathcal{Q}^*_{T-t+1}\left(m-\sum_{s=1}^{t-1}B^{\textsc{ad}}_s,\sum_{s=1}^{t-1} A^{\textsc{ad}}_s\right)\right)$. It then solves Problem~$(\mathcal{S}^*\left(m-\sum_{s=1}^{T-1}B^{\textsc{ad}}_s,\sum_{s=1}^{T-1} A^{\textsc{ad}}_s\right)$ in the last period, which is defined as follows:
\begin{align}
    \min\quad &\left\{A_T:\mathbb{P}\left[\mathrm{Bino}\left(A_T, 1- \frac{\varepsilon\cdot p}{\left(N_0 +1\right)^r}-\varepsilon\cdot(1-p) \right)\geq m\right] \geq 1-\delta,\ A_T\geq0\right\} \tag{$\mathcal{S}^*(m,N_0)$}
\end{align}

\begin{algorithm} [h!]
\caption{Adaptive algorithm to solve Problem $(\mathcal{P}^*)$.}\small \begin{algorithmic}
\item Repeat, for $t=1,\cdots,T-1$:
\begin{itemize}
    \item[] \textbf{1. Optimize.} Define $\beta_t=\alpha_T\left(1-r^{t-1}\right)$ and $\gamma_t$ such that $\sum_{s=1}^{t-1} A^{\textsc{ad}}_s=\gamma_t m^{\beta_t}+o\left(m^{\beta_t}\right)$. Solve Problem $\left(\mathcal{Q}^*_{T-t+1}\left(m-\sum_{s=1}^{t-1}B^{\textsc{ad}}_s,\sum_{s=1}^{t-1} A^{\textsc{ad}}_s\right)\right)$. Retrieve solution $A^\dagger_1,\cdots,A^\dagger_{T-t+1}$.
    \item[] \textbf{2. Commit immediate decision.} Implement the first-period decision: $A^{\textsc{ad}}_t=A^\dagger_1$.
    \item[] \textbf{3. Observe realizations.} Sample $B^{\textsc{ad}}_t\sim \mathrm{Bino}\left(A^{\textsc{ad}}_t, 1- \frac{\varepsilon\cdot p}{\left(\sum_{s=1}^{t-1} A^{\textsc{ad}}_s +1\right)^r}-\varepsilon\cdot(1-p)\right)$.
\end{itemize}
\item $A^{\textsc{ad}}_T\gets\left(\mathcal{S}^*\left(m-\sum_{s=1}^{T-1}B^{\textsc{ad}}_s,\sum_{s=1}^{T-1} A^{\textsc{ad}}_s\right)\right)$. Sample $B^{\textsc{ad}}_T\sim \mathrm{Bino}\left(A^{\textsc{ad}}_T, 1- \frac{\varepsilon\cdot p}{\left(\sum_{s=1}^{T-1} A^{\textsc{ad}}_s +1\right)^r}-\varepsilon\cdot(1-p)\right)$.
\end{algorithmic}
\end{algorithm}

Problem~$\left(\mathcal{Q}^*_{T-t+1}\left(m-\sum_{s=1}^{t-1}B_s,\sum_{s=1}^{t-1} A_s\right)\right)$ is solved via Equations $\mathcal{A}(T,m,\gamma,\beta)$ and $\mathcal{L}(T,m,\gamma,\beta)$ using $\sum_{s=1}^{t-1} A_s=\Theta(\gamma m^\beta)$. We prove by induction over $t=1,\cdots,T-1$ that $$A^{\textsc{ad}}_t=\Theta\left(m^{\alpha_T\left(1-r^t\right)}\right).$$

The result for $t=1$ follows directly from Theorem~\ref{thm:main}. Let us assume that it holds for $t-1\in\{1,\cdots,T-2\}$ and prove it for $t$. In period $t$, the decision-maker solves $\left(\mathcal{Q}^*_{T-t+1}\left(m-\sum_{s=1}^{t-1}B^{\textsc{ad}}_s,\sum_{s=1}^{t-1} A^{\textsc{ad}}_s\right)\right)$, where $\sum_{s=1}^{t-1} A^{\textsc{ad}}_s=\Theta\left(m^{\alpha_T\left(1-r^{t-1}\right)}\right)$ per the induction hypothesis. Let us denote by $\beta_t=\alpha_T\left(1-r^{t-1}\right)$. Let us momentarily assume that  $\delta=o\left(m^{(1-\beta_t)\cdot\alpha_{T-t+1}\cdot(1-r)+\beta_t(1-r)-1}\right)$. Then, per Lemma~\ref{lem:QtmN_det}, we know that the solution of that problem, denoted by $A^\dagger_\tau$, satisfies 
$A^\dagger_\tau=\theta\left(m^{(1-\beta_t)\alpha_{T-t+1}\left(1-r^\tau\right)+\beta_t}\right)$ for $\tau=1,\cdots,T-t+1$. By construction, the adaptive policy follows the first-period solution in the problem solved at time $t$, so that $A^{\textsc{ad}}_t=A^\dagger_1$. Therefore: $A^{\textsc{ad}}_t=\Theta\left(m^{(1-\beta_t)\alpha_{T-t+1}(1-r)+\beta_t}\right)$. We conclude the induction as follows:
\begin{align*}
    (1-\beta_t)\alpha_{T-t+1}(1-r)+\beta_t
    &=\left(1-\alpha_T(1-r^{t-1})\right)\cdot\frac{1}{1-r^{T-t+1}}(1-r)+\alpha_T(1-r^{t-1})\\
    &=\frac{1}{1-r^T}\left(\frac{(r^{t-1}-r^T)(1-r)}{1-r^{T-t+1}}+1-r^{t-1}\right)\\
    &=\frac{1}{1-r^T}\left(r^{t-1}(1-r)+1-r^{t-1}\right)\\
    &=\alpha_T(1-r^t)
\end{align*}

Similarly, the leading-order term in the regret expression does not change over the iterations of the adaptive algorithm. Indeed, per Lemma~\ref{lem:QtmN_det}, the algorithm achieves a regret of $\Theta\left(m^{(1-\beta_t)\cdot\alpha_{T-t+1}\cdot(1-r)+\beta_t(1-r)}\right)$ at each iteration, and
\begin{align*}
    (1-\beta_t)\alpha_{T-t+1}(1-r)+\beta_t(1-r)
    &=\frac{1}{1-r^T}\left(r^{t-1}(1-r)+(1-r^{t-1})(1-r)\right)
    =\alpha_T(1-r)
\end{align*}
Note, also, that this property implies that $\delta=o\left(m^{(1-\beta_t)\cdot\alpha_{T-t+1}\cdot(1-r)+\beta_t(1-r)-1}\right)$, since by assumption $\delta=o\left(m^{\alpha_T(1-r)-1}\right)$, which ensures that the condition of Lemma~\ref{lem:QtmN_det} is satisfied. This concludes the proof that the algorithm maintains a regret of $\Theta\left(m^{\alpha_T\cdot(1-r)}\right)$ at each iteration.

The adaptive algorithm is specified in Algorithm~\ref{alg:adaptive}. At each time period $t=1,\cdots,T-1$, it solves Problem~$\left(\mathcal{Q}^*_{T-t+1}\left(m-\sum_{s=1}^{t-1}B^{\textsc{ad}}_s,\sum_{s=1}^{t-1} A^{\textsc{ad}}_s\right)\right)$. It then solves Problem~$(\mathcal{S}^*\left(m-\sum_{s=1}^{T-1}B^{\textsc{ad}}_s,\sum_{s=1}^{T-1} A^{\textsc{ad}}_s\right)$ in the last period, which is defined as follows:
\begin{align}
    \min\quad &\left\{A_T:\mathbb{P}\left[\mathrm{Bino}\left(A_T, 1- \frac{\varepsilon\cdot p}{\left(N_0 +1\right)^r}-\varepsilon\cdot(1-p) \right)\geq m\right] \geq 1-\delta,\ A_T\geq0\right\} \tag{$\mathcal{S}^*(m,N_0)$}
\end{align}

Repeat, for $t=1,\cdots,T-1$:
\begin{itemize}
