    \item[] \textbf{2. Commit immediate decision.} Implement the first-period decision: $A^{\textsc{ad}}_t=A^\dagger_1$.
    \item[] \textbf{3. Observe realizations.} Sample $B^{\textsc{ad}}_t\sim \mathrm{Bino}\left(A^{\textsc{ad}}_t, 1- \frac{\varepsilon\cdot p}{\left(\sum_{s=1}^{t-1} A^{\textsc{ad}}_s +1\right)^r}-\varepsilon\cdot(1-p)\right)$.
\end{itemize}

Similarly, the leading-order term in the regret expression does not change over the iterations of the adaptive algorithm. Indeed, per Lemma~\ref{lem:QtmN_det}, the algorithm achieves a regret of $\Theta\left(m^{(1-\beta_t)\cdot\alpha_{T-t+1}\cdot(1-r)+\beta_t(1-r)}\right)$ at each iteration, and
\begin{align*}
    (1-\beta_t)\alpha_{T-t+1}(1-r)+\beta_t(1-r)
    &=\frac{1}{1-r^T}\left(r^{t-1}(1-r)+(1-r^{t-1})(1-r)\right)
    =\alpha_T(1-r)
\end{align*}

Repeat, for $t=1,\cdots,T-1$:
    \begin{itemize}
        \item[] \textbf{1. Optimize.} Solve Problem $(\mathcal{P}^*)$ using Algorithm 1 from the paper. Retrieve solution $A^\dagger_1,\cdots,A^\dagger_{T}$.
        \item[] \textbf{2. Commit $T-1$ decisions.} Implement decisions $A^\dagger_1,\cdots,A^\dagger_{T-1}$.
        \item[] \textbf{3. Observe realizations.} Sample $B_t\sim \mathrm{Bino}\left(A^\dagger_t, 1- \frac{\varepsilon\cdot p}{\left(\sum_{s=1}^{t-1} A_s +1\right)^r}-\varepsilon\cdot(1-p)\right)$, $t=1,\cdots,T-1$.
