\end{equation*}

We use $\mathcal{N}(\boldsymbol{y})$ to denote the set of facilities that are tentatively opened during the planning horizon, and $\mathcal{M}(\boldsymbol{y})$ to denote the set of customers with at least one adjacent facility that has been tentatively opened under the decision vector $\boldsymbol{y}=\{y_{it}\mid i=1,\cdots,n,\ t=1,\cdots,T\}$. Formally:
\begin{align*}
    \mathcal{N}(\boldsymbol{y})&=\{i\in\{1,\cdots,n\} \mid \exists t\in\{1,\cdots,T\}:y_{it}=1\}\\
    \mathcal{M}(\boldsymbol{y})&=\{j\in\{1,\cdots,q\} \mid \pi_{j}(\boldsymbol{y})>0\}=\left\{j\in\{1,\cdots,q\}\mid\mathcal{F}_j\cap\mathcal{N}(\boldsymbol{y})\neq\emptyset\right\}
\end{align*}

Consider the graph $\mathcal{G}'$ where all central nodes $\mathcal{F}^\textsc{ctl}(d_\star)\cup \mathcal{C}^\textsc{ctl}(d_\star)$ and all connecting edges are removed. Let the optimal values of the stochastic problem, our algorithm, and the fully-learned problem in $\mathcal{G}'$ as $m_0^*(\varepsilon, T)$, $m_0^\dagger(\varepsilon, T)$, and $m_0^{\textsc{L}}(T)$ respectively. We can construct solutions to the original problems (with $\mathcal{G}$) by adding all central facilities, so that
\begin{align*}
    & m^*(\varepsilon, T)\leq m_0^*(\varepsilon, T)\leq m^*(\varepsilon, T)+|\mathcal{F}^\textsc{ctl}(d_\star)|\\
    & m^\dagger(\varepsilon, T)\leq m_0^\dagger(\varepsilon, T)\leq m^\dagger(\varepsilon, T)+|\mathcal{F}^\textsc{ctl}(d_\star)|\\
    & m^{\textsc{L}}(\varepsilon, T)\leq m_0^{\textsc{L}}(\varepsilon, T)\leq m^{\textsc{L}}(\varepsilon, T)+|\mathcal{F}^\textsc{ctl}(d_\star)|
\end{align*}

\paragraph{Upper bounds.}

Let us start with Problem~\eqref{prob:network}. Lemma~\ref{lem:main_feasible} provides an algorithm that tentatively opens $d_\star c_0\left(m + \varepsilon\cdot p \cdot\zeta_T\cdot m^{\alpha_T\cdot(1-r)} + \Delta(m)\right)$ facilities over $T$ periods, so that at least $d_\star m$ facilities are actually opened with probability at least $1-\delta$. Per our degree assumption, each customer is connected to at most $d_\star$ facilities. Using the same argument as above, any set of $d_\star m$ facilities is connected to at least $m$ customers. This means that the solution satisfies the chance constraint, and defines a feasible solution to problem~\eqref{prob:network}. We have derived a solution that satisfies:
\begin{align*}
    &\sum_{t=1}^T \sum_{i=1}^n y_{it} =d_\star c_0 \left(m + \varepsilon\cdot p \cdot\zeta_T\cdot m^{\alpha_T\cdot(1-r)}+ \Delta(m)\right) \\
    & \mathbb{P}\left[\sum_{t=1}^T \sum_{i=1}^n z_{it} \geq d_\star m\right] \geq 1-\delta\\
    & \mathbb{P}\left[\sum_{j=1}^q s_{jT} \geq m\right] \geq 1-\delta
\end{align*}

Turning to Algorithm~\ref{ALG_network}, define $q=m+\Delta_G(m)$. Using Lemma~\ref{lem:main_bound}, there exists an algorithm such that tentatively opening the following number of facilities
$$\sum_{i=1}^n \sum_{t=1}^T y_{it}=d_\star c_0 \left(q + \varepsilon\cdot p \cdot\zeta_T\cdot q^{\alpha_T\cdot(1-r)} + \Delta(q)\right)$$
would result in the number of opened facilities in expectation such that:
\[\mathbb{E}\left[\sum_{i=1}^n \sum_{t=1}^T z_{it}\right]  \geq d_\star q,\]
for $m$ sufficiently large. Again, since each customer is connected to at most $d_\star$ facilities, any set of $d_\star q$ facilities is connected to at least $q$ customers. Thus, the expected number of connected customers must satisfy:
\[\mathbb{E}\left[\sum_{j=1}^q s_{jT} \geq m\right]\geq\frac{1}{d_\star}\mathbb{E}\left[\sum_{i=1}^n \sum_{t=1}^T z_{it}\right]\geq q\]\

Therefore, opening $d_\star c_0 \left(q + \varepsilon\cdot p \cdot\zeta_T\cdot q^{\alpha_T\cdot(1-r)} + \Delta(q) \right)$ defines a feasible solution for Problem~\eqref{prob:network_ALG}, hence an upper bound to $|\mathcal{N}(\boldsymbol{y}^\dagger)|$. Note that the function within the brackets is concave in $q$ and its derivative is less than 3 for $q$ sufficiently large. Therefore, we obtain:
\begin{align*}
    |\mathcal{N}(\boldsymbol{y}^\dagger)|&\leq d_\star c_0 \left(q + \varepsilon\cdot p \cdot \zeta_T\cdot q^{\alpha_T\cdot(1-r)} + \Delta(q)\right)\\
    &\leq d_\star c_0 \left(m + \varepsilon\cdot p \cdot\zeta_T\cdot m^{\alpha_T\cdot(1-r)} + \Delta(m)+3(q-m)\right)\\
    &= d_\star c_0 \left(m + \varepsilon\cdot p \cdot\zeta_T\cdot m^{\alpha_T\cdot(1-r)}+ \Delta(m)+3\Delta_G(m)\right)
\end{align*}
This completes the proof of Lemma~\ref{lem:sol_bound}.

Let us start with Problem~\eqref{prob:network}. Lemma~\ref{lem:main_feasible} provides an algorithm that tentatively opens $d_\star c_0\left(m + \varepsilon\cdot p \cdot\zeta_T\cdot m^{\alpha_T\cdot(1-r)} + \Delta(m)\right)$ facilities over $T$ periods, so that at least $d_\star m$ facilities are actually opened with probability at least $1-\delta$. Per our degree assumption, each customer is connected to at most $d_\star$ facilities. Using the same argument as above, any set of $d_\star m$ facilities is connected to at least $m$ customers. This means that the solution satisfies the chance constraint, and defines a feasible solution to problem~\eqref{prob:network}. We have derived a solution that satisfies:
\begin{align*}
    &\sum_{t=1}^T \sum_{i=1}^n y_{it} =d_\star c_0 \left(m + \varepsilon\cdot p \cdot\zeta_T\cdot m^{\alpha_T\cdot(1-r)}+ \Delta(m)\right) \\
    & \mathbb{P}\left[\sum_{t=1}^T \sum_{i=1}^n z_{it} \geq d_\star m\right] \geq 1-\delta\\
    & \mathbb{P}\left[\sum_{j=1}^q s_{jT} \geq m\right] \geq 1-\delta
\end{align*}

Let us prove Lemma~\ref{lem:hoeffding_gen_bound} with $\boldsymbol{y} = \boldsymbol{y}^\dagger$. The arguments proceed in the same way for $\boldsymbol{y} = \boldsymbol{y}^*$. We define $\mathcal{D}=(\mathcal{N},\mathcal{A})$ as the dependency graph of the random variables $s_{jT}$, conditioned on the facilities tentatively opened under decision $\boldsymbol{y}$. Each node represents a customer. An edge connects two customers $j$ and $k$ if and only if $s_{jT}$ and $s_{kT}$ are not independent, i.e., if and only if a facility that can cover both has been tentatively opened: $(j,k)\in\mathcal{A}\iff\mathcal{F}_j\cap\mathcal{F}_k\cap\mathcal{N}(\boldsymbol{y})\neq\emptyset$

By assumption, the degree of any node in the customer-facility graph is less than or equal to $d_\star$. Therefore, any customer can share an adjacent facility with up to $d_\star(d_\star-1)$ other customers.
By Brooks' Theorem \citep{brooks1941colouring}, the chromatic number of $\mathcal{D}$ satisfies $\chi(\mathcal{D})\leq (d_\star)^2-d_\star+1\leq (d_\star)^2$. This implies that its fractional chromatic number satisfies $\chi^*(\mathcal{D})\leq \chi(\mathcal{D})\leq (d_\star)^2$.

We use this result to characterize $\left|\sum_{j=1}^q s_{jT} - \pi_{j}(\boldsymbol{y}^\dagger)\right|$. By definition, each variable $s_{jT}$ is bounded by 1. We also need to bound $\mathrm{Var}\left(\sum_{j=1}^q s^\dagger_{jT}\right)$. By definition of $\chi^*(\mathcal{D})$, $s^\dagger_{jT}$ is correlated to at most $\chi^*(\mathcal{D})$ other variables $s^\dagger_{iT}$. Using the inequality $\mathrm{Var}(\sum_{i=1}^n X_i)\leq n \sum_{i=1}^n \mathrm{Var}(X_i)$, we obtain
\[\mathrm{Var}\left(\sum_{j=1}^q s^\dagger_{jT}\right) \leq  \chi^*(\mathcal{D})\ \sum_{j=1}^q \mathrm{Var}(s^\dagger_{jT})\]

Now we separate the cases where $p=1$ and $p\neq 1$.

\underline{Case 1: $p\neq 1$.}
\begin{align*}
	&\mathrm{Var}\left(\sum_{j=1}^q s^\dagger_{jT}\right)
	\\\leq & \chi^*(\mathcal{D})\ \sum_{j=1}^q \mathrm{Var}(s^\dagger_{jT})
	\\\leq & d_\star^2 \sum_{j \in \mathcal{M}(\boldsymbol{y}^\dagger)} \mathrm{Var}(s^\dagger_{jT})
	\\\leq & d_\star^2\sum_{j \in \mathcal{M}(\boldsymbol{y}^\dagger)}  \prod_{\tau=1}^T \left(\frac{\varepsilon\cdot p}{\left(\sum_{s=1}^{\tau-1} \sum_{i=1}^n y^\dagger_{is} + 1\right)^r}+\varepsilon\cdot(1-p)\right)^{\sum_{i \in \mathcal{F}_j} y^\dagger_{i\tau}}
	\\= & d_\star^2\sum_{j \in \mathcal{M}(\boldsymbol{y}^\dagger)}  \prod_{\tau:\sum_{i \in \mathcal{F}_j} y^\dagger_{i\tau}>0 }  \prod_{i:i \in \mathcal{F}_j, y^\dagger_{i\tau}>0 }  \left(\frac{\varepsilon\cdot p}{\left(\sum_{s=1}^{\tau-1} \sum_{i=1}^n y^\dagger_{is} + 1\right)^r}+\varepsilon\cdot(1-p)\right)^{ y^\dagger_{i\tau}}    
	\\\leq & d_\star^2\sum_{j \in \mathcal{M}(\boldsymbol{y}^\dagger)}  \prod_{\tau:\sum_{i \in \mathcal{F}_j} y^\dagger_{i\tau}>0 } \sum_{i: i \in \mathcal{F}_j,  y^\dagger_{i\tau}>0} \left(\frac{\varepsilon\cdot p}{\left(\sum_{s=1}^{\tau-1} \sum_{i=1}^n y^\dagger_{is} + 1\right)^r}+\varepsilon\cdot(1-p)\right)\frac{y^\dagger_{i\tau}}{|i:  y^\dagger_{i\tau}>0|}
	\\\leq & d_\star^2\sum_{j \in \mathcal{M}(\boldsymbol{y}^\dagger)}  \left(\prod_{\tau:\sum_{i \in \mathcal{F}_j} y^\dagger_{i\tau}>0 } \left(\sum_{i: i \in \mathcal{F}_j,  y^\dagger_{i\tau}>0} \left(\frac{\varepsilon\cdot p}{\left(\sum_{s=1}^{\tau-1} \sum_{i=1}^n y^\dagger_{is} + 1\right)^r}+\varepsilon\cdot(1-p)\right)\frac{y^\dagger_{i\tau}}{|i:  y^\dagger_{i\tau}>0|}\right)\right)^{1/|\tau:\sum_{i \in \mathcal{F}_j} y^\dagger_{i\tau}>0 |}
	\\\leq & d_\star^2\sum_{j \in \mathcal{M}(\boldsymbol{y}^\dagger)}  \sum_{\tau:\sum_{i \in \mathcal{F}_j} y^\dagger_{i\tau}>0 }\sum_{i: i \in \mathcal{F}_j,  y^\dagger_{i\tau}>0}\left(\frac{\varepsilon\cdot p}{\left(\sum_{s=1}^{\tau-1} \sum_{i=1}^n y^\dagger_{is} + 1\right)^r}+\varepsilon\cdot(1-p)\right)\frac{y^\dagger_{i\tau}}{|\tau:\sum_{i \in \mathcal{F}_j} y^\dagger_{i\tau}>0 ||i:  y^\dagger_{i\tau}>0|}    
	\\\leq & d_\star^3\sum_{i \in \mathcal{N}(\boldsymbol{y}^\dagger)} \sum_{\tau=1}^T \left(\frac{\varepsilon\cdot p}{\left(\sum_{s=1}^{\tau-1} \sum_{i=1}^n y^\dagger_{is} + 1\right)^r}+\varepsilon\cdot(1-p)\right)y^\dagger_{i\tau}
	\\\leq & \varepsilon d_\star^4 c_0 (m + \varepsilon \cdot p \cdot \zeta_T \cdot m^{\alpha_T \cdot(1-r)} + \Delta(m)+3\Delta_G(m))
	\\\leq& 2\varepsilon d_\star^4 c_0 m
\end{align*}
where in the fourth and sixth inequality, we are using the well-known AM-GM inequality twice. The third last inequality comes from the fact that each $i,\tau$ with $y^\dagger_{i\tau}>0$ has been counted at most $d_\star$ times in the triple sum; the second-to-last inequality comes from Lemma \ref{lem:sol_bound}; and the last inequality holds for sufficiently large $m$. Similarly, since $p\neq1$, the variance of each item satisfies  $\mathrm{Var}(s^\dagger_{jT})>(1-(1-p)\varepsilon)((1-p)\varepsilon)>0$, and therefore $\mathrm{Var}\left(\sum_{j=1}^q s^\dagger_{jT}\right)=\Theta(m)$. This implies:
\[\mathcal{O}\left(\frac{\max_{i} c_i \cdot \chi^*(\mathcal{G})^2 \sum_{i=1}^n \mathbb{E}\left[(X_i-\mathbb{E}[X_i])^3\right]}{\left(\mathrm{Var}\left(\sum_{i=1}^n X_i\right)\right)^{3/2}}\right)=\mathcal{O}\left(\frac{1}{\left(\mathrm{Var}\left(\sum_{i=1}^n X_i\right)\right)^{1/2}}\right)=o(1)\]

From \cite{janisch2024berry}, we have for sufficiently large $m$:
\[\mathbb{P}\left(\left|\sum_{j=1}^q s_{jT} - \pi_{j}(\boldsymbol{y}^\dagger)\right|\geq s\sqrt{2\varepsilon d_\star^4 c_0 m}\right)\leq2\Phi(-s) \]

By construction of $\Delta_G(m)$, we obtain:
\[\mathbb{P}\left(\left|\sum_{j=1}^q s_{jT} - \pi_{j}(\boldsymbol{y}^\dagger)\right|>\Delta_G(m)\right)=\mathbb{P}\left(\left|\sum_{j=1}^q s_{jT} - \pi_{j}(\boldsymbol{y}^\dagger)\right|> -\Phi^{-1}\left(\frac{\delta}{2}\right)\sqrt{2\varepsilon d_\star^4 c_0 m}\right)\leq\delta \]
