\underline{Case 2: $p=1$.}
\begin{align*}
	\mathrm{Var}\left(\sum_{j=1}^q s^\dagger_{jT}\right)





	\leq & d_\star^3\sum_{i \in \mathcal{N}(\boldsymbol{y}^\dagger)} \sum_{\tau=1}^T \left(\frac{\varepsilon}{\left(\sum_{s=1}^{\tau-1} \sum_{i=1}^n y^\dagger_{is} + 1\right)^r}\right)y^\dagger_{i\tau}
	\\\leq & d_\star^4 \varepsilon\left(\zeta_T \cdot m^{\alpha_T \cdot (1-r)} + o\left(m^{\alpha_T \cdot (1-r)} \right)\right)
\end{align*}
where the first inequality follows the same logic as above, and the last inequality can be derived following the same procedure as Lemma \ref{lem:main_feasible}. As in the proof of Lemma \ref{lem:main_feasible}, we also have $\mathrm{Var}\left(\sum_{j=1}^q s^\dagger_{jT}\right)=\Omega(m^{1-\alpha_T\cdot r(1-r)})$. From \cite{janisch2024berry}, we have for sufficiently large $m$:
