\[\mathbb{P}\left(\left|\sum_{j=1}^q s_{jT} - \pi_{j}(\boldsymbol{y}^\dagger)\right|> \Delta_G(m)\right)=\mathbb{P}\left(\left|\sum_{j=1}^q s_{jT} - \pi_{j}(\boldsymbol{y}^\dagger)\right|> -\Phi^{-1}\left(\frac{\delta}{2}\right)\sqrt{2\varepsilon d_\star^4 \zeta_T \cdot m^{\alpha_T \cdot (1-r)} }\right)\leq\delta \]
