Let us define $\boldsymbol{y}^\dagger(m-\Delta)$ as the solution to Problem~\eqref{prob:network_ALG} with the constraint that $m-\Delta$ facilities must open, so the solution to Problem~\eqref{prob:network_ALG} can be written as $\boldsymbol{y}^\dagger\left(m+\Delta_G(m)\right)$:
\begin{align*}
    \boldsymbol{y}^\dagger(m-\Delta)\in\argmin\left\{\sum_{t=1}^T \sum_{i=1}^n y_{it}\ \mid\ \sum_{j=1}^q \pi_{j}(\boldsymbol{y}) \geq m-\Delta;\ \boldsymbol{y} \in \mathbb{Z}^{N \times T}\right\}
\end{align*}

Note that the optimal solution of Problem~\eqref{prob:network} must satisfy the constraint:
\begin{equation}
    \mathbb{P}\left(\sum_{j=1}^q s^*_{jT}\geq m\right)\geq 1-\delta = 1-o\left(m^{\alpha_T\cdot(1-r)-1}\right) \end{equation}
Therefore, we have that:
\begin{align*}
    \mathbb{P}\left(\sum_{j=1}^q s^*_{jT} \geq m \mid \mathcal{E}(\boldsymbol{y}^*)\right)
    &=\frac{\mathbb{P}\left(\sum_{j=1}^q s^*_{jT}\geq m\right)-\mathbb{P}\left(\sum_{j=1}^q s^*_{jT}\mid \mathcal{E}^c(\boldsymbol{y}^*) \right)\mathbb{P}(\mathcal{E}^c(\boldsymbol{y}^*))}{\mathbb{P}(\mathcal{E}(\boldsymbol{y}^*))}\\
    &\geq1-o\left(m^{\alpha_T\cdot(1-r)-1}\right)-\delta\quad\text{(Equation~\eqref{eq:Bmdelta_gen} and Lemma~\ref{lem:hoeffding_gen_bound})}\\
    &=1-o\left(m^{\alpha_T\cdot(1-r)-1}\right)
\end{align*}
This completes the proof of Lemma~\ref{lem:prob_bound}.

We proceed by conditioning on the ``good'' event $\mathcal{E}(\boldsymbol{y}^*)$, as follows:
\begin{align*}
    m^*(\varepsilon, T)
    &=\mathbb{E}\left[\sum_{t=1}^T \sum_{i=1}^n  y^*_{it} \mid \mathcal{E}(\boldsymbol{y}^*)\right]\mathbb{P}(\mathcal{E}(\boldsymbol{y}^*))+\mathbb{E}\left[\sum_{t=1}^T \sum_{i=1}^n  y^*_{it} \mid \mathcal{E}^c(\boldsymbol{y}^*)\right]\mathbb{P}(\mathcal{E}^c(\boldsymbol{y}^*))\\
    &\geq \mathbb{E}\left[\sum_{t=1}^T \sum_{i=1}^n  y^*_{it} \mid \mathcal{E}(\boldsymbol{y}^*)\right]\left(1-\delta\right)\quad\text{(Lemma~\ref{lem:hoeffding_gen_bound})}\\
    &=\mathbb{E}\left[\sum_{t=1}^T \sum_{i=1}^n  y^*_{it} \mid \mathcal{E}(\boldsymbol{y}^*)\right] + o(m^{\alpha_T\cdot(1-r)})\ \text{(Lemma~\ref{lem:sol_bound})}
\end{align*}

Conditioned on the good event, we have:
\begin{align*}
    \sum_{j=1}^q s^*_{jT}&\leq \sum_{j=1}^q \pi_{j}(\boldsymbol{y}^*)+\left|\sum_{j=1}^q (s^*_{jT}-\pi_{j}(\boldsymbol{y}^*))\right|\leq\sum_{j=1}^q \pi_{j}(\boldsymbol{y}^*)+\Delta_G(m)
\end{align*}

By further conditioning on the value of $s^*_{jT}$ and defining $A^*_t = \sum_{i=1}^n y^*_{it}$, we obtain:
\begin{align*}
    m^*(\varepsilon, T)
    &\geq\sum_{\sigma=0}^\infty \mathbb{E}\left[\sum_{t=1}^T A^*_t \mid \mathcal{E}(\boldsymbol{y}^*), \sum_{j=1}^q s^*_{jT}=\sigma\right]\mathbb{P}\left(\sum_{j=1}^q s^*_{jT}=\sigma \mid \mathcal{E}(\boldsymbol{y}^*) \right) + o(m^{\alpha_T\cdot(1-r)})\\
    &\geq\sum_{\sigma=m}^\infty \mathbb{E}\left[\sum_{t=1}^T A^*_t \mid \mathcal{E}(\boldsymbol{y}^*), \sum_{j=1}^q s^*_{jT}=\sigma\right]\mathbb{P}\left(\sum_{j=1}^q s^*_{jT}=\sigma \mid \mathcal{E}(\boldsymbol{y}^*) \right) + o(m^{\alpha_T\cdot(1-r)})\\
    &\geq\mathbb{E}\left[\sum_{t=1}^T A^*_t \mid \mathcal{E}(\boldsymbol{y}^*), \sum_{j=1}^q s^*_{jT}=m\right]\mathbb{P}\left(\sum_{j=1}^q s^*_{jT}\geq m \mid \mathcal{E}(\boldsymbol{y}^*) \right) + o(m^{\alpha_T\cdot(1-r)})\\
    &= \mathbb{E}\left[\sum_{t=1}^T A^*_t \mid \mathcal{E}(\boldsymbol{y}^*), \sum_{j=1}^q s^*_{jT}=m, \sum_{j=1}^q \pi_{j}(\boldsymbol{y}^*)\geq m-\Delta_G(m)\right]\mathbb{P}\left(\sum_{j=1}^q s^*_{jT}\geq m\mid \mathcal{E}(\boldsymbol{y}^*) \right) + o(m^{\alpha_T\cdot(1-r)})
\end{align*}
The first term defines a feasible solution to Problem~\eqref{prob:network_ALG} with a right-hand side of $m-\Delta_G(m)$. Per Lemma~\ref{lem:gen_deter_sol_lower}, the following holds, defining again $q=m+\Delta_G(m)$:
\begin{align*}
   \sum_{t=1}^T \sum_{i=1}^n y_{it}^\dagger\left(m -  \Delta_G(m)\right)
   \geq  &\begin{cases}
   	\sum_{t=1}^T \sum_{i=1}^n y_{it}^\dagger(m)- \Theta(m^{1/2}) & \text{if }p \neq 1\\
   	\sum_{t=1}^T \sum_{i=1}^n y_{it}^\dagger(m)- \Theta(m^{1/2\cdot \alpha_T\cdot(1-r)}) & \text{if }p =1 
   	\end{cases}
   \\= & \begin{cases}
   	\sum_{t=1}^T \sum_{i=1}^n y_{it}^\dagger(q)- \Theta(m^{1/2}) & \text{if }p \neq 1\\
   	\sum_{t=1}^T \sum_{i=1}^n y_{it}^\dagger(q)- \Theta(m^{1/2\cdot \alpha_T\cdot(1-r)}) & \text{if }p =1 
   \end{cases}
\end{align*}
In fact, $\sum_{t=1}^T \sum_{i=1}^n y_{it}^\dagger(q)$ is exactly the objective value achieved with Algorithm~\ref{ALG_network}, that is, $\sum_{t=1}^T \sum_{i=1}^n y_{it}$. Combining this observation with Lemma~\ref{lem:prob_bound}, we obtain:
\begin{align*}
    m^*(\varepsilon, T)
    &\geq \begin{cases}
    	\left(\sum_{t=1}^T \sum_{i=1}^n y_{it}^\dagger -  \Theta(m^{1/2}) \right) \times \left(1-o\left(m^{\alpha_T\cdot(1-r)-1}\right)\right)+ o(m^{\alpha_T\cdot(1-r)}) & \text{if }p \neq 1\\
    	\left(\sum_{t=1}^T \sum_{i=1}^n y_{it}^\dagger -  \Theta(m^{1/2\cdot \alpha_T\cdot(1-r)})\right) \times \left(1-o\left(m^{\alpha_T\cdot(1-r)-1}\right)\right)+ o(m^{\alpha_T\cdot(1-r)}) & \text{if }p =1
    \end{cases}
\end{align*}
Therefore, we conclude:
\begin{align*}
    m^*(\varepsilon, T)
    &\geq m^\dagger (\varepsilon, T)- \begin{cases}
        \mathcal{O}\left(m^{\max\{\alpha_T\cdot (1-r),1/2\}}\right) & \text{if }p \neq 1\\
         o\left(m^{\alpha_T\cdot(1-r)}\right) & \text{if }p = 1
    \end{cases} 
\end{align*}

This completes the proof.

