   \end{cases}
\end{align*}

In fact, $\sum_{t=1}^T \sum_{i=1}^n y_{it}^\dagger(q)$ is exactly the objective value achieved with Algorithm~\ref{ALG_network}, that is, $\sum_{t=1}^T \sum_{i=1}^n y_{it}$. Combining this observation with Lemma~\ref{lem:prob_bound}, we obtain:
\begin{align*}
    m^*(\varepsilon, T)
    &\geq \begin{cases}
    	\left(\sum_{t=1}^T \sum_{i=1}^n y_{it}^\dagger -  \Theta(m^{1/2}) \right) \times \left(1-o\left(m^{\alpha_T\cdot(1-r)-1}\right)\right)+ o(m^{\alpha_T\cdot(1-r)}) & \text{if }p \neq 1\\
    	\left(\sum_{t=1}^T \sum_{i=1}^n y_{it}^\dagger -  \Theta(m^{1/2\cdot \alpha_T\cdot(1-r)})\right) \times \left(1-o\left(m^{\alpha_T\cdot(1-r)-1}\right)\right)+ o(m^{\alpha_T\cdot(1-r)}) & \text{if }p =1
    \end{cases}
\end{align*}

Therefore, we conclude:
\begin{align*}
    m^*(\varepsilon, T)
    &\geq m^\dagger (\varepsilon, T)- \begin{cases}
        \mathcal{O}\left(m^{\max\{\alpha_T\cdot (1-r),1/2\}}\right) & \text{if }p \neq 1\\
         o\left(m^{\alpha_T\cdot(1-r)}\right) & \text{if }p = 1
    \end{cases} 
\end{align*}

This completes the proof.

We denote by $\mathcal{M}_t(\boldsymbol{y}^{\textsc{L}})$ the set of customers first tentatively covered in period $t$:
\begin{align*}
    \mathcal{M}_t(\boldsymbol{y}^{\textsc{L}})&=\left\{j\in\{1,\cdots,q\}:\exists i\in\mathcal{F}_j:y_{i1}=\cdots=y_{i,t-1}=0,\ y_{it}=1,\ y_{k\tau}=0,\ \forall \tau\leq t,\forall k\in\mathcal{F}_j\setminus\{i\}\right\}
\end{align*}

Then, we have:
\begin{align*}
    \sum_{j=1}^q \pi_{j}(\boldsymbol{y}^{\textsc{L}})
    =&\sum_{j=1}^q\left[1-\prod_{\tau=1}^T \left(\frac{\varepsilon}{\left(\sum_{s=1}^{\tau-1}\sum_{i=1}^n y^{\textsc{L}}_{is}+1\right)^r}\right)^{\sum_{i \in \mathcal{F}_j} y^{\textsc{L}}_{i\tau}}\right]\\
    =&\sum_{t=1}^T\sum_{j \in \mathcal{M}_t(\boldsymbol{y}^{\textsc{L}})} \left[1-\prod_{\tau=t}^T \left(\frac{\varepsilon}{\left(\sum_{s=1}^{\tau-1}\sum_{i=1}^n y^{\textsc{L}}_{is}+1\right)^r}\right)^{\sum_{i \in \mathcal{F}_j} y^{\textsc{L}}_{i\tau}}\right]\\
    \leq &\left(\sum_{t=1}^T\sum_{j \in \mathcal{M}_t(\boldsymbol{y}^{\textsc{L}})} 1\right)-\left(\sum_{t=1}^T\sum_{j \in \mathcal{M}_t(\boldsymbol{y}^{\textsc{L}}), \exists k\;s.t.\;j=j^{\textsc{L}}(k)}\prod_{\tau=t}^T \left(\frac{\varepsilon}{\left(\sum_{s=1}^{\tau-1}\sum_{i=1}^n y^{\textsc{L}}_{is}+1\right)^r}\right)^{\sum_{i \in \mathcal{F}_j} y^{\textsc{L}}_{i\tau}}\right]\\
    \overset{{(*)}}{=}& m-\left(\sum_{t=1}^T\sum_{j \in \mathcal{M}_t(\boldsymbol{y}^{\textsc{L}}), \exists k\;s.t.\;j=j^{\textsc{L}}(k)} \left(\frac{\varepsilon}{\left(\sum_{s=1}^{t-1}\sum_{i=1}^n y^{\textsc{L}}_{is}+1\right)^r}\right)y^{\textsc{L}}_{kt}\right)\\
    =&m-\left(\sum_{i=1}^n \frac{\varepsilon\cdot y^{\textsc{L}}_{i,t(i)}}{\left(\sum_{s=1}^{t(i)-1}\sum_{i=1}^n y^{\textsc{L}}_{is}+1\right)^r}\right)\\
    =&m-\sum_{\tau=1}^T\sum_{i=1}^n\frac{\varepsilon\cdot y^{\textsc{L}}_{i\tau}}{\left(\sum_{s=1}^{t-1}\sum_{i=1}^n y^{\textsc{L}}_{is}+1\right)^r}
\end{align*}

Let $\boldsymbol{y}^{\textsc{L-OPT}}$ denote an optimal solution to Problem~\eqref{prob:network_perfect}. Recall that each facility is tentatively opened at most once in that solution, i.e., $\sum_{t=1}^T{y}^{\textsc{L-OPT}}_{it}\in\{0,1\}$ for all $i=1,\cdots,n$. Moreover, the success of each facility is time-invariant, i.e., $S_{it}=S_i$ for all $t=1,\cdots,T$. Therefore, any facility can be opened in any time period in the fully-learned solution. Out of all optimal solutions to Problem~\eqref{prob:network_perfect}, we select one that solves the following problem:
\begin{align*}
    \min_{\boldsymbol{y}\in\{0,1\}^{T \times N}} \quad & \sum_{i=1}^n\sum_{\tau=1}^T\frac{\varepsilon\cdot y_{it}}{\left(\sum_{s=1}^{\tau-1}\sum_{i=1}^n y_{is}+1\right)^r} \nonumber\\
    \text{s.t.}\quad& \sum_{t=1}^Ty_{it}=\sum_{t=1}^T{y}^{\textsc{L-OPT}}_{it},\ \forall i=1,\cdots,n\nonumber
\end{align*}
By construction, the solution is feasible in Problem~\eqref{prob:network_perfect} because of time invariance. Also by construction, the solution achieves the same cost as $\boldsymbol{y}^{\textsc{L-OPT}}$. It therefore remains an optimal solution to Problem~\eqref{prob:network_perfect}. We denote it by $\boldsymbol{y}^{\textsc{L}}$.

We operate the change of variables $A^{\textsc{L-OPT}}_t = \sum_{i=1}^ny^{\textsc{L-OPT}}_{it}$ and $A^{\textsc{L}}_t = \sum_{i=1}^n y^{\textsc{L}}_{it}$. Then, $\mathbf{A}^{\textsc{L}}$ is the optimal solution to the following problem:
\begin{align}
    \max_{\mathbf{A}\in\{0,1\}^T} \quad & \sum_{t=1}^TA_t- \sum_{\tau=1}^T\frac{\varepsilon\cdot A_t}{\left(\sum_{s=1}^{\tau-1}A_s+1\right)^r} \nonumber\\
    \text{s.t.}\quad& \sum_{t=1}^TA_t=\sum_{t=1}^T A^{\textsc{L-OPT}}_{it},\ \forall i=1,\cdots,n\nonumber
\end{align}

This problem now has an equivalent format to  Problem~\eqref{prob:main_det} in Section~\ref{sec:base}. Following the same procedure as Lemma~\ref{lem:main_det}, we can derive a solution such that $\sum_{t=1}^TA_t=m+K(T,\varepsilon,p)\cdot m^{g(r)}+o\left(m^{g(r)}\right)$ and $\sum_{t=1}^TA_t- \sum_{\tau=1}^T\left(\frac{\varepsilon}{(\sum_{s=1}^{\tau-1}A_s+1)^r}\right)A_t\geq\sum_{t=1}^T A^{\textsc{L-OPT}}_{it}\geq m$, so that
\begin{align*}
	\sum_{\tau=1}^T\frac{\varepsilon\cdot A^{\textsc{L}}_t}{\left(\sum_{s=1}^{\tau-1}A^{\textsc{L}}_s+1\right)^r}
	&= \sum_{i=1}^n\sum_{\tau=1}^T\frac{\varepsilon\cdot y^{\textsc{L}}_{it}}{\left(\sum_{s=1}^{\tau-1}\sum_{i=1}^n y^{\textsc{L}}_{is}+1\right)^r}
	=K(T,\varepsilon,p)\cdot m^{g(r)} + o\left(m^{g(r)}\right)
\end{align*}
for some constant $K(T,\varepsilon,p)>0$ that is absolutely bounded above by a constant $K_0<\infty $.

By Lemma~\ref{lem:bound_loss_gen}, we derive:
$$m -d_\star K(T,\varepsilon,p)m^{g(r)}+o\left(m^{g(r)}\right)\leq \sum_{j=1}^q\pi_{j}(\boldsymbol{y}^{\textsc{L}})\leq m -K(T,\varepsilon,p)m^{g(r)}+o\left(m^{g(r)}\right)$$

Therefore, the fully-learned solution $\boldsymbol{y}^{\textsc{L}}$ is feasible in Problem~\eqref{prob:network_ALG} with right-hand side $m - d_\star K(T,\varepsilon,p)\cdot m^{\alpha_T \cdot (1-r)}+o\left(m^{\alpha_T\cdot(1-r)}\right)$, that is:
$$\sum_{t=1}^T \sum_{i=1}^n y_{it}^\dagger\left(m - d_\star K(T,\varepsilon,p)\cdot m^{g(r)}+o\left(m^{g(r)}\right)\right)\leq m^{\textsc{L}}(T)$$

Let us again denote $q=m+\Delta_G(m)$. Lemma~\ref{lem:gen_deter_sol_lower} implies:
\begin{align*}
   &\sum_{t=1}^T \sum_{i=1}^n y_{it}^\dagger\left(m - d_\star K(T,\varepsilon,p)\cdot m^{g(r)}+o\left(m^{g(r)}\right)\right)\\
   &\geq \sum_{t=1}^T \sum_{i=1}^n y_{it}^\dagger(m)-d_\star^2 K(T,\varepsilon,p) m^{g(r)} + o\left(m^{g(r)}\right)\\
   &\geq \sum_{t=1}^T \sum_{i=1}^n y_{it}^\dagger(q)-d_\star \left((q-m)+\mathcal{O}\left((q-m)^{g(r)}\right)\right)-d_\star^2  K(T,\varepsilon,p) m^{g(r)} + o\left(m^{g(r)}\right)\\
   &=	 \sum_{t=1}^T \sum_{i=1}^n y_{it}^\dagger(q)-d_\star^2 K'(T,\varepsilon,p) m^{g(r)} + o\left(m^{g(r)}\right) 
\end{align*}
with
$$K'(T,\varepsilon,p)=\begin{cases}
	K(T,\varepsilon,p)& \text{if }p=1 \text{ or } (p \neq 1 \text{ and } \alpha_T\cdot(1-r)>1/2)\\
	K'(T,\varepsilon,p)+1 & \text{if }p \neq 1\text{ and } \alpha_T\cdot(1-r)\leq 1/2        
\end{cases} $$
Combining these observations, we obtain:
$$m^{\textsc{L}}(T)\geq\sum_{t=1}^T \sum_{i=1}^n y_{it}^\dagger(q)-\mathrm{d}_\star^2 K'(T,\varepsilon,p)\cdot m^{g(r)}+ o\left(m^{g(r)}\right)$$

Moreover, the fully-learned solution $\boldsymbol{y}^{L}$ is optimal in Problem~\eqref{prob:network_ALG} with right-hand side $\sum_{j=1}^q \pi_{j}(\boldsymbol{y}^{L})$. Therefore, we have:
\begin{align*}
    m^{\textsc{L}}(T)&\leq \sum_{t=1}^T \sum_{i=1}^n y_{it}^\dagger\left(\sum_{j=1}^q \pi_{j}(\boldsymbol{y}^{L})\right)
    \leq \sum_{t=1}^T \sum_{i=1}^n y_{it}^\dagger\left(m-K(T,\varepsilon,p)\cdot m^{g(r)}+ o\left(m^{g(r)}\right)\right)
\end{align*}

Again, using Lemma~\ref{lem:gen_deter_sol_lower}, we have:
\begin{align*}
   &\sum_{t=1}^T \sum_{i=1}^n y_{it}^\dagger\left(m - K(T,\varepsilon,p)\cdot m^{g(r)}+o\left(m^{\alpha_T\cdot(1-r)}\right)\right)\\
   &\leq \sum_{t=1}^T \sum_{i=1}^n y_{it}^\dagger(m)-\frac{1}{d_\star}K(T,\varepsilon,p)\cdot m^{g(r)} + o\left(m^{g(r)}\right)\\
   &\leq \sum_{t=1}^T \sum_{i=1}^n y_{it}^\dagger(q)-\frac{1}{d_\star}\left((q-m)+\mathcal{O}\left((q-m)^{g(r)}\right)\right)-\frac{1}{d_\star}K(T,\varepsilon,p)\cdot m^{g(r)} + o\left(m^{g(r)}\right)\\
   &= \sum_{t=1}^T \sum_{i=1}^n y_{it}^\dagger(q)-\frac{1}{d_\star}K'(T,\varepsilon,p)\cdot m^{g(r)} + o\left(m^{g(r)}\right)
\end{align*}

Combining these observations, we obtain:
$$m^{\textsc{L}}(T)\leq\sum_{t=1}^T \sum_{i=1}^n y_{it}^\dagger(q)-\frac{1}{d_\star}K'(T,\varepsilon,p)\cdot m^{g(r)} + o\left(m^{g(r)}\right)$$
We conclude that:
\begin{align*}
    m^\dagger(\varepsilon, T)
    &= m^{\textsc{L}}(T)+\Theta\left(m^{g(r)}\right)
\end{align*}
This completes the proof of Lemma~\ref{lem:network_deter_lower}.

Let $\boldsymbol{y}^{\textsc{L-OPT}}$ denote an optimal solution to Problem~\eqref{prob:network_perfect}. Recall that each facility is tentatively opened at most once in that solution, i.e., $\sum_{t=1}^T{y}^{\textsc{L-OPT}}_{it}\in\{0,1\}$ for all $i=1,\cdots,n$. Moreover, the success of each facility is time-invariant, i.e., $S_{it}=S_i$ for all $t=1,\cdots,T$. Therefore, any facility can be opened in any time period in the fully-learned solution. Out of all optimal solutions to Problem~\eqref{prob:network_perfect}, we select one that solves the following problem:
\begin{align*}
    \min_{\boldsymbol{y}\in\{0,1\}^{T \times N}} \quad & \sum_{i=1}^n\sum_{\tau=1}^T\frac{\varepsilon\cdot y_{it}}{\left(\sum_{s=1}^{\tau-1}\sum_{i=1}^n y_{is}+1\right)^r} \nonumber\\
    \text{s.t.}\quad& \sum_{t=1}^Ty_{it}=\sum_{t=1}^T{y}^{\textsc{L-OPT}}_{it},\ \forall i=1,\cdots,n\nonumber
\end{align*}

We operate the change of variables $A^{\textsc{L-OPT}}_t = \sum_{i=1}^ny^{\textsc{L-OPT}}_{it}$ and $A^{\textsc{L}}_t = \sum_{i=1}^n y^{\textsc{L}}_{it}$. Then, $\mathbf{A}^{\textsc{L}}$ is the optimal solution to the following problem:
\begin{align}
    \max_{\mathbf{A}\in\{0,1\}^T} \quad & \sum_{t=1}^TA_t- \sum_{\tau=1}^T\frac{\varepsilon\cdot A_t}{\left(\sum_{s=1}^{\tau-1}A_s+1\right)^r} \nonumber\\
    \text{s.t.}\quad& \sum_{t=1}^TA_t=\sum_{t=1}^T A^{\textsc{L-OPT}}_{it},\ \forall i=1,\cdots,n\nonumber
\end{align}

This problem now has an equivalent format to  Problem~\eqref{prob:main_det} in Section~\ref{sec:base}. Following the same procedure as Lemma~\ref{lem:main_det}, we can derive a solution such that $\sum_{t=1}^TA_t=m+K(T,\varepsilon,p)\cdot m^{g(r)}+o\left(m^{g(r)}\right)$ and $\sum_{t=1}^TA_t- \sum_{\tau=1}^T\left(\frac{\varepsilon}{(\sum_{s=1}^{\tau-1}A_s+1)^r}\right)A_t\geq\sum_{t=1}^T A^{\textsc{L-OPT}}_{it}\geq m$, so that
\begin{align*}
	\sum_{\tau=1}^T\frac{\varepsilon\cdot A^{\textsc{L}}_t}{\left(\sum_{s=1}^{\tau-1}A^{\textsc{L}}_s+1\right)^r}
	&= \sum_{i=1}^n\sum_{\tau=1}^T\frac{\varepsilon\cdot y^{\textsc{L}}_{it}}{\left(\sum_{s=1}^{\tau-1}\sum_{i=1}^n y^{\textsc{L}}_{is}+1\right)^r}
	=K(T,\varepsilon,p)\cdot m^{g(r)} + o\left(m^{g(r)}\right)
\end{align*}
for some constant $K(T,\varepsilon,p)>0$ that is absolutely bounded above by a constant $K_0<\infty $.

Moreover, the fully-learned solution $\boldsymbol{y}^{L}$ is optimal in Problem~\eqref{prob:network_ALG} with right-hand side $\sum_{j=1}^q \pi_{j}(\boldsymbol{y}^{L})$. Therefore, we have:
\begin{align*}
    m^{\textsc{L}}(T)&\leq \sum_{t=1}^T \sum_{i=1}^n y_{it}^\dagger\left(\sum_{j=1}^q \pi_{j}(\boldsymbol{y}^{L})\right)
    \leq \sum_{t=1}^T \sum_{i=1}^n y_{it}^\dagger\left(m-K(T,\varepsilon,p)\cdot m^{g(r)}+ o\left(m^{g(r)}\right)\right)
\end{align*}

We conclude that:
\begin{align*}
    m^\dagger(\varepsilon, T)
    &= m^{\textsc{L}}(T)+\Theta\left(m^{g(r)}\right)
\end{align*}
This completes the proof of Lemma~\ref{lem:network_deter_lower}.

\paragraph{Part 1.}

We prove that Algorithm~\ref{ALG_network} yields a feasible solution to~\eqref{prob:network}. By definition of Problem~\eqref{prob:network_ALG}:
\[\sum_{j=1}^q \pi_{j}(\boldsymbol{y}^\dagger) \geq m + \Delta_G(m)\]

Conditioned on $\mathcal{E}(\boldsymbol{y}^\dagger)$, we have:
\begin{align*}
    \sum_{j=1}^q s^\dagger_{jT}&\geq \sum_{j=1}^q \pi_{j}(\boldsymbol{y}^\dagger)-\left|\sum_{j=1}^q (s^\dagger_{jT}-\pi_{j}(\boldsymbol{y}^\dagger)\right|\geq\sum_{j=1}^q \pi_{j}(\boldsymbol{y}^\dagger)-\Delta_G(m)\geq m
\end{align*}

This implies from Lemma \ref{lem:hoeffding_gen_bound} that $\mathbb{P}\left(\sum_{j=1}^q s^\dagger_{jT}\geq m\right)\geq \mathbb{P}(\mathcal{E}(\boldsymbol{y}^\dagger))\geq 1-\delta$. Therefore, the decision vector $\boldsymbol{y}^\dagger$ defines a feasible solution to Problem~\eqref{prob:network}. From Lemma~\ref{lem:network_deter_stochstic}, we also have
$$m^\dagger(\varepsilon, T)\leq m^*(\varepsilon, T)+\begin{cases}
	o\left(m^{\alpha_T \cdot (1-r)}\right)& \text{if }p=1 \text{ or } (p \neq 1 \text{ and } \alpha_T\cdot(1-r)>1/2)\\
	\mathcal{O}(m^{1/2}) & \text{if }p \neq 1\text{ and } \alpha_T\cdot(1-r)\leq 1/2        
\end{cases} $$

\paragraph{Part 2.} This is obtained from Lemmas~\ref{lem:network_deter_stochstic} and~\ref{lem:network_deter_lower}, when $p=1$:
\begin{align*}
       & m^\dagger(\varepsilon, T)\leq m^*(\varepsilon, T)+o\left(m^{\alpha_T\cdot(1-r)}\right)\\
       & m^\dagger(\varepsilon, T) =  m^{\textsc{L}}(T) +\Theta(m^{g(r)}) =  m^{\textsc{L}}(T) +\Theta(m^{\alpha_T(1-r)})
\end{align*}
This proves Part 2 of the theorem: $m^*(\varepsilon, T) =  m^{\textsc{L}}(T) +\Theta(m^{\alpha_T(1-r)}) =  m^{\textsc{L}}(T)+\Theta(m^{g(r)})$.

