As in Lemma~\ref{lem:gen_deter_sol_lower}, let us define $\boldsymbol{y}^{\mathrm{NL}}(m-\Delta)$ as the solution to Problem~\eqref{prob:network_nolearn} with the constraint that $m-\Delta$ facilities must open with probability $1-\delta$:
\begin{align*}
    \boldsymbol{y}^{NL}(m-\Delta)\in\argmin \quad & \sum_{t=1}^T \sum_{i=1}^n y_{it} \\
    \text{s.t.}\quad&\mathbb{P}\left[\sum_{j=1}^q s_{jT} \geq m-\Delta\right] \geq 1-\delta\\
    \quad& s_{jT}\sim \mathrm{Ber}\left(1-\prod_{\tau=1}^T \varepsilon^{\sum_{i \in \mathcal{F}_j} y_{i\tau}}\right),\quad \forall j\in\mathcal{C}\\
    \quad& y_{it}\in\{0,1\},\ \forall i\in \mathcal{F}, \ \forall t\in\mathcal{T}
\end{align*}

Recall that $\sum_{t=1}^Ty^{\textsc{L}}_{it}\leq 1, \;\;\forall i=1,\cdots,n$ and that $|\mathcal{M}(\boldsymbol{y}^{\mathrm{L}})|=m$. The expected customer coverage of the fully-learned solution in the no-learning problem satisfies:
\begin{align*}
    \mathbb{E}\left[\sum_{j=1}^q s_{jT}\right]
    &= \sum_{j=1}^q\left(1-\prod_{\tau=1}^T \varepsilon^{\sum_{i \in \mathcal{F}_j} y_{i\tau}^{\mathrm{L}}} \right)\\
    &=\sum_{j \in \mathcal{M}(\boldsymbol{y}^{\mathrm{L}})} \left(1 - \prod_{\tau=1}^T \varepsilon^{\sum_{i \in \mathcal{F}_j} y_{i\tau}^{\mathrm{L}}}\right) \\
    &=\sum_{j \in \mathcal{M}(\boldsymbol{y}^{\mathrm{L}})} \left(1 - \varepsilon^{\sum_{i \in \mathcal{F}_j} \sum_{\tau=1}^Ty_{i\tau}^{\mathrm{L}}}\right) \\
    &\leq\sum_{j \in \mathcal{M}(\boldsymbol{y}^{\mathrm{L}})} \left(1 - \varepsilon^{d_\star}\right) \\
    &=  m - m \varepsilon^{d_\star}
\end{align*}

For notational ease, we focus on the case where $p=1$, but all arguments trivially to the case with $p\in[0,1]$. The proof proceeds by swapping decisions $y^\dagger_{i_1,t} \to y^\dagger_{i_1,\tau}$ and $y^\dagger_{i_2,\tau} \to y^\dagger_{i_2,t}$. This swap does not change the coverage of any customer other than those in the neighborhood of the two facilities. It also leaves the objective function of Problem~\eqref{prob:network_ALG} unchanged. Denote the new decisions as $\widetilde{\boldsymbol{y}}^\dagger$. Given that $y^\dagger_{it}$ is the optimal solution to Problem~\eqref{prob:network_ALG}, it is without loss of generality to assume that the left-hand side of the constraint is at least as large under $y^\dagger_{it}$ as under $\widetilde{y}^\dagger_{it}$, i.e.:
\[\sum_{j \in \mathcal{C}_{i_1} \cup \mathcal{C}_{i_2}}^q \left(1-\prod_{\tau=1}^T \left(\frac{\varepsilon}{\left(\sum_{s=1}^{\tau-1} \sum_{i=1}^n y^\dagger_{is} +1\right)^r}\right)^{\sum_{i \in \mathcal{F}_j} y^\dagger_{iv}}\right)\geq \sum_{j \in \mathcal{C}_{i_1} \cup \mathcal{C}_{i_2}}^q \left(1-\prod_{v=1}^T \left(\frac{\varepsilon}{\left(\sum_{s=1}^{v-1} \sum_{i=1}^n \widetilde{y}^\dagger_{is} +1\right)^r}\right)^{\sum_{i \in \mathcal{F}_j} \widetilde{y}^\dagger_{iv}}\right)\]

We can simplify this expression by noting that $\sum_{i \in \mathcal{F}_j} \widetilde{y}^\dagger_{iv}=\sum_{i \in \mathcal{F}_j} y^\dagger_{iv}$ for all $j\in\mathcal{C}\setminus(\mathcal{C}_{i_1}\cup\mathcal{C}_{i_2})$ and for all $v\in\mathcal{T}$:
\begin{align*}
    &\sum_{j \in \mathcal{C}_{i_1} \setminus \mathcal{C}_{i_2}}^q \prod_{\tau=1}^T \left(\frac{\varepsilon}{\left(\sum_{s=1}^{\tau-1} \sum_{i=1}^n y^\dagger_{is} +1\right)^r}\right)^{\sum_{i \in \mathcal{F}_j} y^\dagger_{iv}-\mathbf{1}\{v=t\}} \left(\left(\frac{\varepsilon}{\left(\sum_{s=1}^{t-1} \sum_{i=1}^n y^\dagger_{is} +1\right)^r}\right)-\left(\frac{\varepsilon}{\left(\sum_{s=1}^{\tau-1} \sum_{i=1}^n y^\dagger_{is} +1\right)^r}\right)\right)
    \\+&\sum_{j \in \mathcal{C}_{i_2} \setminus \mathcal{C}_{i_1}}^q \prod_{\tau=1}^T \left(\frac{\varepsilon}{\left(\sum_{s=1}^{\tau-1} \sum_{i=1}^n y^\dagger_{is} +1\right)^r}\right)^{\sum_{i \in \mathcal{F}_j} y^\dagger_{iv}-\mathbf{1}\{v=\tau\}} \left(\left(\frac{\varepsilon}{\left(\sum_{s=1}^{\tau-1} \sum_{i=1}^n y^\dagger_{is} +1\right)^r}\right)-\left(\frac{\varepsilon}{\left(\sum_{s=1}^{t-1} \sum_{i=1}^n y^\dagger_{is} +1\right)^r}\right)\right)\\
    &\leq 0
\end{align*}
Further simplification results in:
\begin{align*}
    &\sum_{j \in \mathcal{C}_{i_1} \setminus \mathcal{C}_{i_2}}^q \prod_{\tau=1}^T \left(\frac{\varepsilon}{\left(\sum_{s=1}^{\tau-1} \sum_{i=1}^n y^\dagger_{is} +1\right)^r}\right)^{\sum_{i \in \mathcal{F}_j} y^\dagger_{iv}-\mathbf{1}\{v=t\}}\\
    &-\sum_{j \in \mathcal{C}_{i_2} \setminus \mathcal{C}_{i_1}}^q \prod_{\tau=1}^T \left(\frac{\varepsilon}{\left(\sum_{s=1}^{\tau-1} \sum_{i=1}^n y^\dagger_{is} +1\right)^r}\right)^{\sum_{i \in \mathcal{F}_j} y^\dagger_{iv}-\mathbf{1}\{v=\tau\}}
    \leq 0
\end{align*}
We use a similar switching argument to show that those facilities that do not get selected have a smaller expected incremental coverage than those that do get selected.

